local CourtFanMaker = {}
local PRODUCTS = {
    simple_feather_court_fan = { name = "Preprosta peresna dvorna pahljača", leatherCost = 1, woolCost = 2, woodCost = 1, time = 3, cost = 60, prestige = 5, happiness = 2, description = "Preprosta peresna dvorna pahljača za dvorne dame." },
    silk_pleated_court_fan = { name = "Svilo nagubana dvorna pahljača", silkCost = 2, leatherCost = 1, woodCost = 1, time = 6, cost = 180, prestige = 12, happiness = 3, description = "Svilo nagubana dvorna pahljača za trgovce." },
    silver_spined_court_fan = { name = "Srebrnahrbetna dvorna pahljača", silkCost = 2, silverCost = 1, leatherCost = 1, woodCost = 1, time = 9, cost = 440, prestige = 22, happiness = 4, description = "Srebrnahrbetna dvorna pahljača za plemiče." },
    gold_trimmed_court_fan = { name = "Zlatookrasna dvorna pahljača", silkCost = 3, goldCost = 1, silverCost = 1, leatherCost = 1, woodCost = 1, time = 13, cost = 1000, prestige = 35, happiness = 6, description = "Zlatookrasna dvorna pahljača za visoke plemiče." },
    jewel_set_court_fan = { name = "Draguljasta dvorna pahljača", silkCost = 3, goldCost = 1, silverCost = 1, leatherCost = 1, woodCost = 1, jewelCost = 1, time = 17, cost = 2200, prestige = 50, happiness = 8, description = "Dvorna pahljača z draguljem za visoko plemstvo." },
    royal_grand_court_fan = { name = "Kraljevski veliki dvorna pahljača", silkCost = 5, goldCost = 3, silverCost = 2, leatherCost = 1, woodCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 5000, prestige = 72, happiness = 13, description = "Velika kraljevska dvorna pahljača z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    court_fan_workshop = { name = "Dvorna pahljačna delavnica", cost = { gold = 260, wood = 120, stone = 120, silk = 6, leather = 6 }, upkeep = 6, qualityBonus = 5 },
    ceremonial_loft = { name = "Slovesna podstrešje", cost = { gold = 950, wood = 280, stone = 240, silver = 6, gold = 4 }, upkeep = 22, qualityBonus = 18 },
    master_fan_atelier = { name = "Mojstrski pahljačni atelje", cost = { gold = 2700, wood = 380, stone = 520, silver = 32, gold = 6 }, upkeep = 62, qualityBonus = 30 },
    royal_ceremony_palace = { name = "Kraljevska slovesna palača", cost = { gold = 11500, wood = 580, stone = 760, gold = 75, jewel = 18 }, upkeep = 230, qualityBonus = 55, prestigeBonus = 50 },
}
CourtFanMaker.silkStock = 14; CourtFanMaker.leatherStock = 10; CourtFanMaker.woodStock = 10; CourtFanMaker.woolStock = 8; CourtFanMaker.silverStock = 6; CourtFanMaker.goldStock = 6; CourtFanMaker.jewelStock = 4; CourtFanMaker.pearlStock = 4
CourtFanMaker.productStock = {}; CourtFanMaker.buildings = {}; CourtFanMaker.maker = nil; CourtFanMaker.activeMaking = {}; CourtFanMaker.totalProducts = 0; CourtFanMaker.dayTimer = 0
function CourtFanMaker.init() CourtFanMaker.silkStock=14; CourtFanMaker.leatherStock=10; CourtFanMaker.woodStock=10; CourtFanMaker.woolStock=8; CourtFanMaker.silverStock=6; CourtFanMaker.goldStock=6; CourtFanMaker.jewelStock=4; CourtFanMaker.pearlStock=4; CourtFanMaker.productStock={}; CourtFanMaker.buildings={}; CourtFanMaker.maker=nil; CourtFanMaker.activeMaking={}; CourtFanMaker.totalProducts=0; CourtFanMaker.dayTimer=0; print("[CourtFanMaker] Royal Court Fan Maker System initialized (6 products, 4 buildings)") end
function CourtFanMaker.hireMaker(n,s) s=s or math.random(55,90); local c=540+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; CourtFanMaker.maker={name=n or ("Pahljačar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Pahljačar najet: %s (spretnost: %d)",CourtFanMaker.maker.name,s),"success") end; return true end
function CourtFanMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function CourtFanMaker.build(id) local ok,e=CourtFanMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(CourtFanMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function CourtFanMaker.getQualityBonus() local b=0; for _,bd in ipairs(CourtFanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function CourtFanMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.silkCost and CourtFanMaker.silkStock<(d.silkCost or 0) then return false,"Premalo svile" end; if d.leatherCost and CourtFanMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.woodCost and CourtFanMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.woolCost and CourtFanMaker.woolStock<(d.woolCost or 0) then return false,"Premalo volne" end; if d.silverCost and CourtFanMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and CourtFanMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and CourtFanMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and CourtFanMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #CourtFanMaker.buildings==0 then return false,"Potrebna dvorna pahljačna delavnica" end; if not CourtFanMaker.maker then return false,"Potreben pahljačar" end; return true end
function CourtFanMaker.make(pt,qty) qty=qty or 1; local ok,e=CourtFanMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.silkCost then CourtFanMaker.silkStock=CourtFanMaker.silkStock-d.silkCost*qty end; if d.leatherCost then CourtFanMaker.leatherStock=CourtFanMaker.leatherStock-d.leatherCost*qty end; if d.woodCost then CourtFanMaker.woodStock=CourtFanMaker.woodStock-d.woodCost*qty end; if d.woolCost then CourtFanMaker.woolStock=CourtFanMaker.woolStock-d.woolCost*qty end; if d.silverCost then CourtFanMaker.silverStock=CourtFanMaker.silverStock-d.silverCost*qty end; if d.goldCost then CourtFanMaker.goldStock=CourtFanMaker.goldStock-d.goldCost*qty end; if d.jewelCost then CourtFanMaker.jewelStock=CourtFanMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then CourtFanMaker.pearlStock=CourtFanMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if CourtFanMaker.maker then t=math.max(1,t-math.floor(CourtFanMaker.maker.skill/13)) end; table.insert(CourtFanMaker.activeMaking,{id="courtfan_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function CourtFanMaker.completeMaking(m) local q=1.0+(CourtFanMaker.getQualityBonus()/100); if CourtFanMaker.maker then q=q+(CourtFanMaker.maker.skill/140) end; q=math.min(2.5,q); CourtFanMaker.productStock[m.productType]=(CourtFanMaker.productStock[m.productType] or 0)+m.quantity; CourtFanMaker.totalProducts=CourtFanMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if CourtFanMaker.maker then CourtFanMaker.maker.itemsMade=CourtFanMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then CourtFanMaker.maker.skill=math.min(100,CourtFanMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Dvorna pahljača izdelana: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"courtfan.completed",{productName=m.productName,prestige=m.prestige,happiness=m.happiness}) end end
function CourtFanMaker.update(dt) if not _G.state then return end; CourtFanMaker.dayTimer=CourtFanMaker.dayTimer+dt; if CourtFanMaker.dayTimer>=30 then CourtFanMaker.dayTimer=0; for i=#CourtFanMaker.activeMaking,1,-1 do local m=CourtFanMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then CourtFanMaker.completeMaking(m); table.remove(CourtFanMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(CourtFanMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if CourtFanMaker.maker then tu=tu+14 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function CourtFanMaker.getStats() return {silkStock=CourtFanMaker.silkStock,leatherStock=CourtFanMaker.leatherStock,woodStock=CourtFanMaker.woodStock,woolStock=CourtFanMaker.woolStock,silverStock=CourtFanMaker.silverStock,goldStock=CourtFanMaker.goldStock,jewelStock=CourtFanMaker.jewelStock,pearlStock=CourtFanMaker.pearlStock,productStock=CourtFanMaker.productStock,numBuildings=#CourtFanMaker.buildings,hasMaker=CourtFanMaker.maker~=nil,makerName=CourtFanMaker.maker and CourtFanMaker.maker.name or "—",makerSkill=CourtFanMaker.maker and CourtFanMaker.maker.skill or 0,activeMaking=#CourtFanMaker.activeMaking,totalProducts=CourtFanMaker.totalProducts} end
return CourtFanMaker
